import Foundation

func transform(_ value: Int) async -> Int { value * value }

func run() async -> [Int] {
    await withTaskGroup(of: Int.self, returning: [Int].self) { group in
        for value in 1...5 { group.addTask { await transform(value) } }
        var results: [Int] = []
        for await result in group { results.append(result) }
        return results.sorted()
    }
}

print(await run())
